"use client";
import * as React from "react";
import { cn } from "../lib/utils";
export interface UploadSoundStatusProps { duration?: number; compact?: boolean; className?: string; onComplete?: () => void; fileName?: string; fileSizeMB?: number; cancelable?: boolean; muted?: boolean; }
export function UploadSoundStatus({ duration = 2400, compact = false, className, onComplete, fileName = "davinciui-components.zip", fileSizeMB = 48.6, cancelable = true, muted = false }: UploadSoundStatusProps) {
 const [progress, setProgress] = React.useState(0); const [done, setDone] = React.useState(false); const [cancelled, setCancelled] = React.useState(false); const context = React.useRef<AudioContext | null>(null); const runId = React.useRef(0);
 const uploading = progress > 0 && progress < 100;
 const speed = fileSizeMB / Math.max(0.2, duration / 1000);
 const remainingMB = Math.max(0, (fileSizeMB * (100 - progress)) / 100);
 const eta = uploading ? Math.max(1, Math.ceil(remainingMB / Math.max(0.1, speed))) : 0;
 const ping = (frequency: number) => { const audio = context.current ?? (context.current = new AudioContext()); const osc = audio.createOscillator(); const gain = audio.createGain(); osc.frequency.value = frequency; gain.gain.setValueAtTime(.12, audio.currentTime); gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + .12); osc.connect(gain).connect(audio.destination); osc.start(); osc.stop(audio.currentTime + .13); };
 const start = async () => { const id = ++runId.current; setDone(false); setCancelled(false); setProgress(1); const startAt = performance.now(); const step = (now: number) => { if (runId.current !== id) return; const value = Math.min(100, Math.round(((now - startAt) / duration) * 100)); setProgress(value); if (value < 100) requestAnimationFrame(step); else { setDone(true); if (!muted) ping(760); onComplete?.(); } }; requestAnimationFrame(step); };
 const cancel = () => { runId.current += 1; setProgress(0); setDone(false); setCancelled(true); };
 const status = done ? "Upload complete" : uploading ? `Uploading… ${speed.toFixed(1)} MB/s • ${eta}s left` : cancelled ? "Upload cancelled" : "Waiting to upload";
 return <div className={cn("w-full max-w-md rounded-[1.5rem] border border-[#dce3d2] bg-[#fbfcf7] p-4 text-[#1f271d] shadow-[0_20px_54px_rgba(53,70,40,.12)] dark:border-white/10 dark:bg-[#151a12] dark:text-white", compact ? "p-3" : "p-5 sm:p-6", className)}>
 <style>{`@keyframes upload-stripes { from { background-position: 0 0; } to { background-position: 22px 0; } } @media (prefers-reduced-motion: reduce) { .upload-stripes-animated { animation: none !important; } }`}</style>
 <div className="flex items-center justify-between gap-3"><div><p className="text-sm font-semibold">Upload status</p>{!compact && <p className="mt-1 text-xs text-[#718067] dark:text-white/55">Sound-backed feedback for transfer states.</p>}</div><span className={cn("grid size-9 place-items-center rounded-full", done ? "bg-[#dff3d5] text-[#36752f] dark:bg-[#75d766]/15 dark:text-[#a6ed9b]" : "bg-[#edf0e8] text-[#75806e] dark:bg-white/8 dark:text-white/50")}>{done ? "✓" : "↑"}</span></div>
 <div className="mt-4 flex items-center gap-2.5 rounded-xl border border-[#e2e7dc] bg-white/70 px-3 py-2 dark:border-white/10 dark:bg-white/[.04]"><span className="grid size-8 shrink-0 place-items-center rounded-lg bg-[#edf0e8] text-[#5c6b58] dark:bg-white/8 dark:text-white/60"><svg viewBox="0 0 24 24" aria-hidden="true" className="size-4 fill-none stroke-current stroke-[1.8]"><path d="M6 2h8l4 4v14a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V3a1 1 0 0 1 1-1Zm7 1v5h5" /></svg></span><span className="min-w-0 flex-1"><span className="block truncate text-xs font-semibold">{fileName}</span><span className="block text-[11px] tabular-nums text-[#718067] dark:text-white/55">{fileSizeMB.toFixed(1)} MB</span></span><span className="text-xs font-semibold tabular-nums">{progress}%</span></div>
 <div className="mt-3"><div className="h-2 overflow-hidden rounded-full bg-[#e8ece1] dark:bg-white/10"><div className={cn("h-full rounded-full bg-[#6da55d]", uploading && "upload-stripes-animated")} style={uploading ? { width: `${progress}%`, backgroundImage: "repeating-linear-gradient(-55deg, rgba(255,255,255,.28) 0 6px, transparent 6px 11px)", animation: "upload-stripes .7s linear infinite" } : { width: `${progress}%`, transition: "width .2s" }} /></div><div className="mt-2 flex justify-between text-[11px] tabular-nums text-[#718067] dark:text-white/55"><span>{status}</span>{uploading && <span>{remainingMB.toFixed(1)} MB left</span>}</div></div>
 {uploading && cancelable
   ? <button type="button" onClick={cancel} className="mt-4 w-full rounded-xl border border-[#d8ded4] bg-transparent py-2.5 text-xs font-semibold text-[#5c665a] transition hover:bg-black/[.04] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#6da55d] focus-visible:ring-offset-2 active:scale-[.98] dark:border-white/15 dark:text-white/70 dark:hover:bg-white/[.06] dark:focus-visible:ring-offset-[#151a12]">Cancel upload</button>
   : <button type="button" onClick={() => void start()} disabled={uploading} className="mt-4 w-full rounded-xl bg-[#2e5531] py-2.5 text-xs font-semibold text-white transition hover:bg-[#3d7040] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#6da55d] focus-visible:ring-offset-2 active:scale-[.98] disabled:opacity-60 dark:focus-visible:ring-offset-[#151a12]">{done || cancelled ? "Upload again" : "Start upload"}</button>}
 </div>;
}
export default UploadSoundStatus;
